import { cn } from '@cascivo/core/pure'
import type { CSSProperties, HTMLAttributes } from 'react'
import styles from './logo.module.css'

/**
 * The cascivo mark ("the Notch") on its 32-unit grid: a filled square with a
 * 21x10 bite out of the right edge. Stem 11, bars 11. One closed path.
 */
const MARK_PATH = 'M0 0H32V11H11V21H32V32H0Z'

/** Below this the notch closes optically — use the wordmark alone. */
const MIN_MARK_PX = 16

export type LogoVariant = 'mark' | 'mark-accent' | 'horizontal' | 'stacked' | 'nav'

export interface LogoProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * The logo renders the mark and, in a lockup, the wordmark — there is no slot for
   * anything else. `never` rather than `Omit<>` because omitting a key off
   * `HTMLAttributes` loses the `style` widening that the signals JSX augmentation
   * applies in an adopter's project, and the spread below then fails to compile there.
   */
  children?: never
  /**
   * `mark` and `mark-accent` render the square alone; `horizontal`, `stacked` and `nav`
   * add the wordmark. `nav` is the only lockup permitted below 24px.
   *
   * @defaultValue `mark`
   * @see the component manifest
   */
  variant?: LogoVariant
  /**
   * Mark height in px. Clamped to a 16px floor — below that the notch closes optically.
   *
   * @defaultValue `18` for `nav`, `32` otherwise
   * @see the component manifest
   */
  size?: number
}

function Mark({ accent, size, labelled }: { accent: boolean; size: number; labelled: boolean }) {
  return (
    <svg
      viewBox="0 0 32 32"
      width={size}
      height={size}
      className={styles['mark'] as string | undefined}
      // In a lockup the wordmark already names the brand, so the mark leaves the
      // a11y tree rather than having a screen reader announce "cascivo" twice.
      {...(labelled ? { role: 'img' } : { 'aria-hidden': true })}
    >
      {labelled && <title>cascivo</title>}
      <path d={MARK_PATH} fill="currentColor" />
      {accent && <rect x="11" y="11" width="21" height="10" className={styles['notch']} />}
    </svg>
  )
}

/**
 * The cascivo logo: the mark on its own, or one of the three sanctioned lockups.
 *
 * Renders inline SVG rather than an `<img>` on purpose — `currentColor` and
 * `--cascivo-color-accent` only resolve when the SVG is part of the document, which is
 * what lets the logo repaint with whatever `data-theme` subtree it is dropped into.
 */
export function Logo({ variant = 'mark', size, className, style, ...props }: LogoProps) {
  const markSize = Math.max(size ?? (variant === 'nav' ? 18 : 32), MIN_MARK_PX)
  const isLockup = variant === 'horizontal' || variant === 'stacked' || variant === 'nav'

  return (
    <span
      data-cascivo-logo={variant}
      className={cn(styles['logo'], className as string | undefined)}
      // The caller's style spreads last so it can still override anything, but it
      // no longer replaces the size hook the gap and wordmark are derived from.
      //
      // The cast on `style` is load-bearing in the OTHER type world, not ours: with
      // `@preact/signals-react`'s JSX augmentation loaded — every adopter that installs
      // the signals runtime — `style` widens to `Signalish<CSSProperties | undefined>`,
      // and a union carrying a non-object member is not spreadable (TS2698). Our own
      // tsconfig never loads that augmentation, so a type-aware lint run inside this
      // repo will call it unnecessary. It is not. See CLAUDE.md, "two type worlds".
      style={
        {
          '--cascivo-logo-size': `${markSize}px`,
          ...(style as CSSProperties | undefined),
        } as CSSProperties
      }
      {...props}
    >
      <Mark accent={variant !== 'mark' && variant !== 'nav'} size={markSize} labelled={!isLockup} />
      {isLockup && <span className={styles['wordmark']}>cascivo</span>}
    </span>
  )
}

@layer cascivo.component {
  .logo {
    /* --cascivo-logo-size is the mark height, set inline from the `size` prop. */
    display: inline-flex;
    align-items: center;
    color: inherit;

    /* Horizontal lockup: gap is 1/3 of the mark height. */
    gap: calc(var(--cascivo-logo-size, 2rem) / 3);

    &[data-cascivo-logo='stacked'] {
      /* Stacked is left aligned, never centred; gap is 1/4 of the mark height. */
      flex-direction: column;
      align-items: flex-start;
      gap: calc(var(--cascivo-logo-size, 2rem) / 4);
    }

    /* The nav lockup is the one place the ratio is fixed rather than derived:
       18px mark, 16px wordmark, 10px gap. */
    &[data-cascivo-logo='nav'] {
      gap: 0.625rem;
    }
  }

  .mark {
    display: block;
    flex-shrink: 0;
  }

  .notch {
    fill: var(--cascivo-color-accent);
  }

  .wordmark {
    font-family: var(--cascivo-font-display);
    font-weight: 900;
    /* The wordmark is 16px against an 18px mark — hold that ratio as the mark scales. */
    font-size: calc(var(--cascivo-logo-size, 2rem) * 16 / 18);
    letter-spacing: -0.05em;
    line-height: 1;
    /* The wordmark is lowercase, full stop — surrounding chrome must not restyle it. */
    text-transform: none;
    white-space: nowrap;
    color: currentColor;
  }

  .logo[data-cascivo-logo='nav'] .wordmark {
    font-size: 1rem;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Logo',
  description: 'The cascivo mark and its sanctioned lockups, as inline SVG',
  category: 'display',
  clientJs: 'none',
  states: [],
  variants: ['mark', 'mark-accent', 'horizontal', 'stacked', 'nav'],
  sizes: [],
  props: [
    {
      name: 'variant',
      description:
        '`mark` and `mark-accent` render the square alone; `horizontal`, `stacked` and `nav` add the wordmark. `nav` is the only lockup permitted below 24px.',
      type: "'mark' | 'mark-accent' | 'horizontal' | 'stacked' | 'nav'",
      required: false,
      default: 'mark',
    },
    {
      name: 'size',
      description:
        'Mark height in px. Clamped to a 16px floor — below that the notch closes optically.',
      type: 'number',
      required: false,
      default: '18 for `nav`, 32 otherwise',
    },
  ],
  tokens: ['--cascivo-color-accent', '--cascivo-font-display'],
  styleHooks: ['data-cascivo-logo'],
  accessibility: {
    role: 'img',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Mark', code: '<Logo />' },
    {
      title: 'Two colour',
      code: '<Logo variant="mark-accent" />',
      description: 'The accent fills the notch. Decoration — the mark is complete without it.',
    },
    { title: 'Horizontal lockup', code: '<Logo variant="horizontal" />' },
    {
      title: 'Nav lockup',
      code: '<Logo variant="nav" />',
      description: '18px mark, 16px wordmark, 10px gap — the only lockup allowed below 24px.',
    },
    { title: 'Stacked', code: '<Logo variant="stacked" size={48} />' },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['logo', 'brand', 'mark', 'wordmark', 'lockup', 'identity'],
  intent: {
    whenToUse: [
      'Placing the cascivo logo in a header, footer, auth screen or splash',
      'Needing the mark to repaint with the surrounding data-theme instead of shipping a per-theme image',
      'Any spot that would otherwise hand-roll the logo SVG or point an <img> at logo.svg',
    ],
    whenNotToUse: [
      "Rendering an adopter's own brand — this is the cascivo mark, not a generic logo slot; pass your own node to AuthLayout's `logo` or ShellHeader's `brand` instead",
      'Below 16px — the notch closes optically; use the wordmark alone',
      'Favicons and app icons, which are static files with their own optical centring (see https://cascivo.com/docs/brand)',
    ],
    antiPatterns: [
      {
        bad: '<img src="/logo.svg" alt="cascivo" />',
        good: '<Logo variant="horizontal" />',
        why: 'currentColor and --cascivo-color-accent only resolve when the SVG is inline, so an <img> cannot follow the theme',
      },
      {
        bad: '<Logo variant="mark" style={{ transform: "scaleX(1.4)" }} />',
        good: '<Logo variant="mark" size={48} />',
        why: 'The mark is always 1:1 and never scales on one axis',
      },
      {
        bad: 'Wrapping the logo in chrome that sets text-transform: uppercase',
        good: 'Leave the wordmark lowercase — the component pins text-transform: none',
        why: 'The wordmark is lowercase cascivo; uppercasing it is a misuse of the mark',
      },
    ],
    related: [
      {
        name: 'ShellHeader',
        relationship: 'contained-by',
        reason: 'The nav lockup is what the header brand slot takes',
      },
    ],
    a11yRationale:
      'The bare mark carries role="img" and a <title> so it is announced as "cascivo"; in a lockup the wordmark is real text, so the mark goes aria-hidden rather than announcing the name twice',
    flexibility: [
      {
        area: 'size',
        level: 'flexible',
        note: 'Any size at or above the 16px floor; the wordmark and gap scale from it',
      },
      {
        area: 'variant',
        level: 'strict',
        note: 'A closed set of five. Do not invent a lockup — clear space, gaps and ratios are specified at https://cascivo.com/docs/brand',
      },
      {
        area: 'colour',
        level: 'strict',
        note: 'Ink is currentColor and the notch is --cascivo-color-accent. Never recolour the ink off-token or fill the notch with anything else',
      },
    ],
  },
}
